"""Explicitly synthetic TTIS assets generated by the real two-stage preparation."""
import h5py
import numpy as np
import yaml

from .data import Bundle
from .demo import create_demo
from .io import write_json
from .ttis_data import prepare_ttis


def create_ttis_demo(output, dimension=16, classes=2, secondary=False):
    root = create_demo(output, patients=30 if classes == 3 else 20, dimension=dimension, classes=classes)
    rng = np.random.default_rng(79)
    semantic_dim = 12 if secondary else dimension
    text = rng.normal(size=(classes, semantic_dim)).astype(np.float32)
    text /= np.linalg.norm(text, axis=1, keepdims=True)
    np.save(root/'text.npy', text)
    write_json(root/'semantic.json', {'schema_version': 1, 'classes': [f'class_{i}' for i in range(classes)],
        'synthetic': True, 'model': 'synthetic frozen semantic fixture', 'weights_sha256': '0'*64,
        'embedding_space': 'synthetic_semantic', 'visual_embedding_space': 'synthetic_semantic',
        'provenance': 'synthetic fixture; not natural MUSK or WSI output', 'dimension': semantic_dim,
        'text_path': 'text.npy', 'prompts': [f'synthetic class {i}' for i in range(classes)],
        'prompt_class_indices': list(range(classes)), 'logit_scale': 2.65926})
    bundle = Bundle(root)
    guidance = None
    if secondary:
        guidance = {}
        for row in bundle.records('test'):
            x, coords = bundle.load(row)
            path = root/(row['slide_id']+'_semantic.h5')
            with h5py.File(path, 'w') as f:
                f['features'] = rng.normal(size=(len(x), semantic_dim)).astype(np.float32)
                f['coords'] = coords.numpy()
            guidance[row['slide_id']] = path
    manifest = prepare_ttis(bundle, root/'ttis_assets', root/'semantic.json', 'sklearn_cpu',
                            clusters=16, n_init=2, guidance=guidance)
    task = yaml.safe_load((root/'task.yaml').read_text())
    task['encoders']['toy']['ttis'] = {'manifest': str(manifest)}
    (root/'task.yaml').write_text(yaml.safe_dump(task))
    return root
